using IDSFintech.Api.DTOs; using IDSFintech.Api.Repositories; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace IDSFintech.Api.Controllers;
[ApiController,Authorize,Route("api/[controller]")] public sealed class DeploymentsController(IPortalRepository r):ControllerBase { [HttpGet] public async Task<IActionResult> All(int? clientId,int? productId)=>Ok(new ApiResponse<object>("Deployments retrieved.",await r.DeploymentsAsync(clientId,productId))); [HttpPost,Authorize(Roles="CEO,Manager")] public async Task<IActionResult> Add(DeploymentRequest x){var id=await r.AddDeploymentAsync(x);return Created($"/api/deployments/{id}",new{message="Deployment created.",data=new{id}});} [HttpPut("{id:int}"),Authorize(Roles="CEO,Manager")] public async Task<IActionResult> Edit(int id,DeploymentRequest x)=>await r.UpdateDeploymentAsync(id,x)?Ok(new{message="Deployment updated."}):NotFound(new{message="Deployment not found."}); [HttpDelete("{id:int}"),Authorize(Roles="CEO,Manager")] public async Task<IActionResult> Delete(int id)=>await r.DeleteDeploymentAsync(id)?NoContent():NotFound(new{message="Deployment not found."}); }
